/// Maps an in-memory Dart object to a format-agnostic [ValueKind].
ValueKind dartObjectToValueKind(Object? v) => switch (v) {
  null => ValueKind.nullValue,
  bool() => ValueKind.boolean,
  num() => ValueKind.number,
  String() => ValueKind.string,
  List() => ValueKind.list,
  Map() => ValueKind.map,
  _ => throw CodableException('Unexpected value kind for $v'),
};

/// Parses a JSON object from [reader] into an in-memory `Map<String, Object?>`.
Map<String, Object?> parseObjectFromReader(JsonTokenReader reader) {
  reader.beginObject();
  final map = <String, Object?>{};
  while (reader.moveNext()) {
    final key = reader.nextName();
    map[key] = _parseValueFromReader(reader);
  }
  reader.endObject();
  return map;
}

Object? _parseValueFromReader(JsonTokenReader reader) {
  final type = reader.peek();
  switch (type) {
    case JsonTokenType.nullValue:
      reader.readNull();
      return null;
    case JsonTokenType.boolean:
      return reader.readBool();
    case JsonTokenType.number:
      return reader.readNum();
    case JsonTokenType.string:
      return reader.readString();
    case JsonTokenType.beginObject:
      return parseObjectFromReader(reader);
    case JsonTokenType.beginArray:
      reader.beginArray();
      final list = <Object?>[];
      while (reader.moveNext()) {
        list.add(_parseValueFromReader(reader));
      }
      reader.endArray();
      return list;
    default:
      reader.skipValue();
      return null;
  }
}

